// The airlock plane mecha's cluster places for a declared effect, booted the
// way a consumer boots it: a bayt project holding the cluster's #Runtime with
// two effects, their bridge packaged by activepieces-package.ts, generated by
// bayt into its own .bayt/ and brought up through its launch closure, which
// carries every fragment and the networks the cluster declares
// (compose.networks.yaml, a `compose.includes` file). The project is written
// for the run under this directory and removed with it, so no app has to
// declare an effect for bayt's lowering of the plane to run.
//
// The world outside is a compose file beside it, standing on the networks the
// cluster goes out on, each on a documentation range: the declared sink (the
// fixture pair testdata/mecha-airlock/sink.pem, which the effect's endpoint
// trusts) and an undeclared one on the daprd's `airlock-egress`, and Mailpit,
// as smtp.mailpit.test, on the bridge's `bridge-mail-egress`. The second
// effect reaches Mailpit through the cluster's mail bridge, and signs its body
// with the key its effect declares, which only the compose environment holds.
//
//   mise x -- deno task test:airlock

import assert from "node:assert/strict";
import { packageHatch, writePackage } from "./activepieces-package.ts";
import { fileURLToPath } from "node:url";

const PRONTO = fileURLToPath(new URL("./", import.meta.url)).replace(/\/$/, "");
const ROOT = fileURLToPath(new URL("../../", import.meta.url)).replace(/\/$/, "");
const MECHA = `${ROOT}/libraries/mecha`;
const FIXTURE = `${PRONTO}/testdata/mecha-airlock`;
const RUN = crypto.randomUUID().slice(0, 8);
const DIR = `.mecha-airlock-${RUN}`;
const PROJECT = `mecha-airlock-${RUN}`;
const TAG = `airlock-${RUN}`;
// The bayt project's name, which prefixes every service it lowers.
const P = "mecha_airlock_smoke";
// Commit to settled, with nothing poking the airlock: its worker hears the
// interpreter's enqueue at the commit.
const SETTLE_MS = 3000;
// Where the outbound networks stand: halves of TEST-NET-2, routed nowhere.
const EGRESS = { "airlock-egress": "198.51.100.0/25", "bridge-mail-egress": "198.51.100.128/25" };
const ECHO = "mendhak/http-https-echo:35@sha256:440ca6b810bc04606aac700e461caca5543eaa882c4e0af96a33424d05a23592";
const MAILPIT = "axllent/mailpit:v1.31.4@sha256:b68349e3a014b90c5610bfb26b2ae36f3892d7b8cf25ee140c6c71c98d2fcf48";
// The key the bridged effect signs with, which reaches only the airlock's environment.
const SIGNING_KEY = `smoke-${RUN}`;
const SERVICE_JWT =
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoic2VydmljZSIsInN1YiI6IjAwMDAwMDAwLTAwMDAtMDAwMC0wMDAwLTAwMDAwMDAwMDAwMCIsImV4cCI6MTk4ODE1MDQwMH0.dGYz_sMSnOvZy0eANh7spJbgyr2fEzeynOERIqW7gd4";

// mecha's own steps the cluster's crud, auth and sync read, beside the
// fixture's.
const MIGRATIONS = [
  `${MECHA}/services/database/migrations/000_extensions.sql`,
  `${MECHA}/services/database/migrations/001_roles.sql`,
  `${MECHA}/services/database/migrations/002_grants.sql`,
  `${MECHA}/services/database/007_identity.sql`,
  `${FIXTURE}/migrations/005_publication.sql`,
  `${FIXTURE}/migrations/009_airlock_smoke.sql`,
];

const interpreterMigration = await Deno.readTextFile(`${FIXTURE}/migrations/009_airlock_smoke.sql`);
const interpreters = [...interpreterMigration.matchAll(/CREATE FUNCTION[\s\S]*?END \$\$;/g)].map(([sql]) => sql.replace("CREATE FUNCTION", "CREATE OR REPLACE FUNCTION"));
assert.equal(interpreters.length, 2);

const BAYT_CUE = `package fixture

import (
	bayt "bonisoft.org/plugins/bayt/core:bayt"
	cluster "bonisoft.org/libraries/mecha:cluster"
)

_cluster: cluster.#Cluster & {
	meta: {
		app: "airlock"
		images: {${["database", "mesh", "conduit", "auth", "ticker", "clock", "compute", "airlock"].map((k) => `"${k}": ref: "libraries_mecha:${k}-image"`).join(", ")}}
		airlock:   "effects.json"
		caddyfile: "Caddyfile"
		bounds: {authStatementMs: 5000, tickerCallMs: 35000}
	}
	state: {
		migrations: [${MIGRATIONS.map((m) => `"migrations/${m.split("/").pop()}"`).join(", ")}]
		pipelines: [], schedules: []
		effects: [
			{name: "probe", origin: "https://sink.mecha.test:8443", handler: "effects/probe.js", endpoint: "dapr/probe.yaml"},
			{name: "confirm", bridge: "mail", handler: "effects/confirm.js", endpoint: "dapr/confirm.yaml", secrets: ["CONFIRM_SIGNING_KEY"]},
		]
		effectInterpreters: ${JSON.stringify(interpreters.join("\n\n"))}
		// The runner itself is the local stand-in: the test points its SMTP inside the stack.
		bridges: [{name: "mail", container: "bridge-mail", action: "sendMail", simulator: {}}]
	}
	capabilities: auth: true
	surface: targets: "bridge-mail": (cluster.#ActivepiecesContainer & {
		image: {ref: "libraries_mecha:activepieces-image"}
		source: "activepieces/integrations"
	}).target
}

networks: _cluster.surface.networks

_where: {dir: "plugins/pronto/${DIR}"}
_fixture: bayt.#project & _where & {
	name: "${P}"
	compose: includes: ["compose.networks.yaml"]
	targets: (cluster.#Runtime & {project: _fixture.name, cluster: _cluster}).targets
	targets: launch: compose: up: true
}
project: _fixture
`;

type Out = { ok: boolean; code: number; stdout: string; stderr: string };

async function run(cmd: string, args: string[], opts: { cwd?: string; env?: Record<string, string> } = {}): Promise<Out> {
  const out = await new Deno.Command(cmd, { args, cwd: opts.cwd ?? PRONTO, env: { BAYT_IMAGE_TAG: TAG, ...opts.env }, stdout: "piped", stderr: "piped" }).output();
  const text = (b: Uint8Array) => new TextDecoder().decode(b).trim();
  return { ok: out.success, code: out.code, stdout: text(out.stdout), stderr: text(out.stderr) };
}

async function must(p: Promise<Out>, what: string): Promise<string> {
  const o = await p;
  if (!o.ok) throw new Error(`${what} failed (${o.code}):\n${o.stderr}\n${o.stdout}`);
  return o.stdout;
}

const sink = (network: string, alias: string) => ({
  image: `mecha-airlock-sink:${TAG}`,
  build: {
    context: FIXTURE,
    dockerfile_inline: `FROM ${ECHO}\nCOPY --chmod=644 sink.pem /app/fullchain.pem\nCOPY --chmod=644 sink.key /app/privkey.pem`,
  },
  networks: { [network]: { aliases: [alias] } },
});

/** The fixture project: the cluster's files where its bayt.cue names them, generated by bayt. */
async function generate(dir: string) {
  await must(run("mise", ["exec", "github:denoland/deno@v2.9.7", "--", "deno", "task", "--frozen-lockfile", "build"], { cwd: `${MECHA}/pieces/mail` }), "build mail package");
  await Deno.mkdir(`${dir}/pieces/mail/dist`, { recursive: true });
  for (const file of ["package.json", "dist/index.js", "send.input.schema.json", "send.output.schema.json", "mail.auth.schema.json"]) {
    await Deno.copyFile(`${MECHA}/pieces/mail/${file}`, `${dir}/pieces/mail/${file}`);
  }
  await Deno.copyFile(`${FIXTURE}/pieces/mail.lock`, `${dir}/pieces/mail.lock`);
  const declaration = JSON.parse(await Deno.readTextFile(`${FIXTURE}/activepieces.json`));
  await writePackage(`${dir}/activepieces/integrations`, await packageHatch(dir, declaration));
  for (const sub of ["effects", "dapr", "migrations"]) await Deno.mkdir(`${dir}/${sub}`, { recursive: true });
  const copies: [string, string][] = [
    [`${FIXTURE}/effects.json`, "effects.json"],
    [`${FIXTURE}/effects/probe.js`, "effects/probe.js"],
    [`${FIXTURE}/effects/confirm.js`, "effects/confirm.js"],
    [`${FIXTURE}/dapr/confirm.yaml`, "dapr/confirm.yaml"],
    [`${FIXTURE}/dapr/probe.yaml`, "dapr/probe.yaml"],
    [`${MECHA}/services/proxy/Caddyfile`, "Caddyfile"],
    ...MIGRATIONS.map((m): [string, string] => [m, `migrations/${m.split("/").pop()}`]),
  ];
  for (const [from, to] of copies) await Deno.copyFile(from, `${dir}/${to}`);
  // Caddy's startup hashes files under each declared root, including this fixture.
  await Deno.writeTextFile(`${dir}/Caddyfile`, (await Deno.readTextFile(`${dir}/Caddyfile`)).replace(/:(\{\$PORT:)?8080\}? \{/, "$&\n\troot * /usr/share/caddy"));
  await Deno.writeTextFile(`${dir}/bayt.cue`, BAYT_CUE);
  const networks = JSON.parse(await must(run("cue", ["export", ".", "-e", "networks", "--out", "json"], { cwd: dir }), "cue export networks"));
  await Deno.writeTextFile(`${dir}/compose.networks.yaml`, JSON.stringify({ networks }));
  // bayt's generator as sayt's auto-bayt rule runs it, under the workspace's nu.
  const nu = `use ${ROOT}/plugins/sayt/auto-bayt.nu docker-env; with-env (docker-env) { cd ${dir}; use ${ROOT}/plugins/bayt/core/generate.nu; generate --runtime plugins/bayt }`;
  await must(run("mise", ["-C", ROOT, "x", "--", "nu", "-c", nu]), "bayt generate");
}

Deno.test("the airlock plane bayt lowers reaches its declared sink, and nothing else reaches out", async (t) => {
  const dir = `${PRONTO}/${DIR}`;
  const world = `${dir}/world.yaml`;
  const compose = (args: string[]) =>
    run("docker", ["compose", "-p", PROJECT, "-f", `${dir}/.bayt/compose.launch.closure.yaml`, "-f", world, ...args], { env: { CONFIRM_SIGNING_KEY: SIGNING_KEY } });
  const exec = (target: string, cmd: string[]) => compose(["exec", "-T", `${P}-${target}`, ...cmd]);
  // A one-off of launch, busybox on the default network, as every service but
  // the airlock's is.
  const onDefault = (cmd: string[]) => run("docker", ["run", "--rm", "--network", `${PROJECT}_default`, `bayt-${P}-launch:${TAG}`, ...cmd]);
  const logs = async (service: string) => await must(compose(["logs", "--no-log-prefix", service]), `logs ${service}`);
  const hits = async (service: string, needle = '"path"') => (await logs(service)).split("\n").filter((l) => l.includes(needle)).length;
  const sql = (query: string) => must(exec("database", ["psql", "-U", "postgres", "-d", "airlock", "-X", "-v", "ON_ERROR_STOP=1", "-qtA", "-c", query]), query);
  const wget = (args: string[]) => exec("airlock-mesh", ["/busybox", "wget", "-q", "-T", "8", "-O", "-", ...args]);

  try {
    await generate(dir);
    await Deno.writeTextFile(world, JSON.stringify({
      services: {
        sink: sink("airlock-egress", "sink.mecha.test"),
        other: sink("airlock-egress", "other.mecha.test"),
        mailpit: { image: MAILPIT, ports: ["127.0.0.1::8025"], networks: { "bridge-mail-egress": { aliases: ["smtp.mailpit.test"] } } },
      },
      networks: Object.fromEntries(Object.entries(EGRESS).map(([nw, subnet]) => [nw, { ipam: { config: [{ subnet }] } }])),
    }, null, 2));
    await must(compose(["up", "-d", "--build", "--wait", "--wait-timeout", "400", "bayt", `${P}-launch`, "sink", "other", "mailpit"]), "up");
    const sinkAddress = await must(run("docker", ["inspect", "-f", "{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}", `${PROJECT}-sink-1`]), "inspect sink");

    const call = (endpoint: string, path: string, key: string) =>
      wget(["--header", "Content-Type: application/json", "--header", `Idempotency-Key: ${key}`, "--post-data", "{}", `http://127.0.0.1:3500/v1.0/invoke/${endpoint}/method${path}`]);

    await t.step("a call of the declared endpoint reaches its sink, verified by the endpoint's root", async () => {
      const before = await hits("sink");
      const got = await call("probe", "/v1/a", "smoke:a");
      assert.equal(got.ok, true, got.stderr);
      assert.equal(JSON.parse(got.stdout).headers.host, "sink.mecha.test:8443");
      assert.equal(await hits("sink") - before, 1);
    });

    await t.step("the wall keeps a mistaken target from leaving", async () => {
      for (const path of ["/v1.0/invoke/https://other.mecha.test:8443/method/x", "/v1.0/invoke/other/method/x", "/v1.0/bindings/other", "/x"]) {
        const got = await wget(["--post-data", "{}", `http://127.0.0.1:3500${path}`]);
        assert.equal(got.ok, false, path);
        assert.match(got.stderr, /400/, path);
      }
      assert.equal(await hits("other"), 0);
    });

    // A name on a network the prober is not on fails to resolve whether or not
    // its own networks are internal; only an address shows the route.
    await t.step("the airlock reaches no origin and no bridge, only its daprd", async () => {
      for (const [hostname, port] of [["sink.mecha.test", 8443], [sinkAddress, 8443], ["bridge-mail", 8080]] as const) {
        const got = await exec("airlock", ["deno", "eval", `await Deno.connect({hostname: "${hostname}", port: ${port}})`]);
        assert.equal(got.ok, false, `${hostname}:${port}`);
        if (hostname === sinkAddress) assert.match(got.stderr, /Network is unreachable/);
      }
      assert.equal((await exec("airlock", ["deno", "eval", `(await Deno.connect({hostname: "airlock-mesh", port: 3500})).close()`])).ok, true, "its daprd");
    });

    await t.step("nothing on the default network reaches the daprd or a bridge", async () => {
      for (const url of ["http://airlock-mesh:3500/v1.0/healthz", "http://bridge-mail:8080/send"]) {
        const got = await onDefault(["wget", "-q", "-T", "3", "-O", "-", url]);
        assert.equal(got.ok, false, url);
        assert.match(got.stderr, /bad address|resolve/, `${url}: ${got.stderr}`);
      }
    });

    await t.step("the ledger is closed to the service token and to anon at crud", async () => {
      // crud publishes no port; the one-off stands on its network. busybox
      // wget succeeds on a 2xx alone.
      const get = (path: string, headers: Record<string, string> = {}) =>
        onDefault(["wget", "-q", "-T", "8", "-O", "/dev/null", ...Object.entries(headers).flatMap(([k, v]) => ["--header", `${k}: ${v}`]), `http://crud:3000${path}`]);
      const bearer = { authorization: `Bearer ${SERVICE_JWT}` };
      const accepted = await get("/airlock_smoke", bearer);
      assert.equal(accepted.ok, true, `the token is one crud accepts: ${accepted.stderr}`);
      for (const headers of [bearer, {}]) {
        for (const h of [headers, { ...headers, "accept-profile": "airlock" }]) {
          const got = await get("/external_effect_ledger", h);
          assert.equal(got.ok, false, JSON.stringify(h));
          assert.match(got.stderr, /server returned error: HTTP\/1\.1 4\d\d/, JSON.stringify(h));
        }
      }
    });

    await t.step("a committed transition into the invoking state settles at once, the sink called once", async () => {
      const t0 = performance.now();
      await sql("UPDATE airlock_smoke SET status = 'charging' WHERE id = 'settles'");
      let status = "";
      while (performance.now() - t0 < SETTLE_MS) {
        status = await sql("SELECT status FROM airlock_smoke WHERE id = 'settles'");
        if (status !== "charging") break;
        await new Promise((r) => setTimeout(r, 100));
      }
      const elapsed = Math.round(performance.now() - t0);
      console.log(`W1 commit to settled: ${elapsed} ms`);
      assert.equal(status, "settled");
      assert.equal(await sql("SELECT outcome->>'kind' || ',' || entered FROM airlock.external_effect_ledger WHERE key = 'probe:settles'"), "done,1");
      assert.equal(await hits("sink", "probe:settles"), 1);
      assert.ok(elapsed <= SETTLE_MS);
    });

    await t.step("a claim re-arms the ticker's one-shot row, and its sweep emits a wake that reaches the airlock", async () => {
      assert.equal(await sql("SELECT cron IS NULL AND due_at IS NOT NULL AND last_tick_at IS NULL FROM schedule WHERE name = 'airlock'"), "t");
      const poke = await onDefault(["wget", "-q", "-O", "-", "--post-data", "", "--header", `Authorization: Bearer ${SERVICE_JWT}`, "http://ticker:9998/poke?caller=plane"]);
      assert.equal(poke.ok, true, `${poke.stderr.split("\n").filter((l) => !/ Building| Built/.test(l)).join("\n")}\n${await logs(`${P}-ticker`)}`);
      // compose run writes its build progress to stdout ahead of the command's.
      const report = JSON.parse(poke.stdout.trim().split("\n").pop()!);
      assert.deepEqual(report.schedules.find((s: { schedule: string }) => s.schedule === "airlock"), { schedule: "airlock", emitted: 1, late: 0, held: 0, behind: false });
      assert.deepEqual(report.poke, { ok: true });
      assert.equal(await sql("SELECT count(*) FROM airlock_wake WHERE schedule = 'airlock'"), "1");
      // Armed once per sweep, however many claims; and not again until the next
      // claim. The watermark is the tick's instant, which the ticker spells to
      // the millisecond.
      assert.equal(await sql("SELECT date_trunc('milliseconds', last_tick_at) = date_trunc('milliseconds', due_at) FROM schedule WHERE name = 'airlock'"), "t");
      const again = JSON.parse((await onDefault(["wget", "-q", "-O", "-", "--post-data", "", "--header", `Authorization: Bearer ${SERVICE_JWT}`, "http://ticker:9998/poke?caller=plane"])).stdout.trim().split("\n").pop()!);
      assert.equal(again.schedules.find((s: { schedule: string }) => s.schedule === "airlock").emitted, 0);
      assert.equal(again.poke, undefined);
    });

    await t.step("a bridged effect's mail arrives through the bridge, keyed by the ledger and signed with the key the airlock handed in", async () => {
      const api = `http://${await must(compose(["port", "mailpit", "8025"]), "mailpit port")}/api/v1`;
      await sql("UPDATE airlock_smoke_mail SET status = 'sending' WHERE id = 'b1'");
      let status = "";
      for (let i = 0; i < 60 && status !== "sent"; i++) {
        await new Promise((r) => setTimeout(r, 250));
        status = await sql("SELECT status FROM airlock_smoke_mail WHERE id = 'b1'");
      }
      assert.equal(status, "sent", await logs(`${P}-airlock`));
      const { messages } = await (await fetch(`${api}/messages`)).json();
      assert.equal(messages.length, 1);
      const m = await (await fetch(`${api}/message/${messages[0].ID}`)).json();
      const id = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode("confirm:b1")));
      assert.equal(m.MessageID, `${Array.from(id, (b) => b.toString(16).padStart(2, "0")).join("")}@airlock.test`);
      assert.deepEqual(m.To.map((a: { Address: string }) => a.Address), ["ana@oracle.test"]);
      const parts = [...m.Attachments, ...m.Inline].map((a: { ContentType: string }) => a.ContentType.split(";")[0]);
      assert.ok(parts.includes("text/calendar") || parts.includes("application/ics"), `parts: ${parts}`);
      const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(SIGNING_KEY), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
      const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode("Booking b1 confirmed.")));
      assert.match(m.Text, new RegExp(`signature: ${Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("")}`));
      assert.equal(await sql("SELECT outcome->>'kind' || ',' || entered FROM airlock.external_effect_ledger WHERE key = 'confirm:b1'"), "done,1");
    });

    await t.step("the bridge runs the Deno mail action with a fixed SMTP destination", async () => {
      const config = JSON.parse(await must(run("docker", ["inspect", "-f", "{{json .Config}}", `${PROJECT}-${P}-bridge-mail-1`]), "inspect bridge"));
      assert.equal(config.Cmd.at(-1), "/runner/main.ts");
      const manifest = JSON.parse(await must(exec("bridge-mail", ["cat", "/app/manifest.json"]), "inspect action manifest"));
      assert.equal(manifest.actions.sendMail.fixedProps.host, "smtp.mailpit.test");
      assert.equal(manifest.actions.sendMail.fixedProps.port, 1025);
      assert.equal(manifest.actions.sendMail.fixedProps.starttls, false);
      assert.equal((await exec("bridge-mail", ["java", "-version"])).ok, false, "release contains no JVM");
      assert.match(await must(exec("bridge-mail", ["deno", "--version"]), "Deno version"), /^deno 2\.9\.7\b/);
    });

    await t.step("a rolled-back transition claims nothing and enqueues nothing", async () => {
      await sql("BEGIN; UPDATE airlock_smoke SET status = 'charging' WHERE id = 'rolls-back'; ROLLBACK;");
      await new Promise((r) => setTimeout(r, SETTLE_MS));
      assert.equal(
        await sql("SELECT (SELECT status FROM airlock_smoke WHERE id = 'rolls-back') || ',' || (SELECT count(*) FROM airlock.external_effect_ledger WHERE key = 'probe:rolls-back') || ',' || (SELECT count(*) FROM graphile_worker.jobs)"),
        "pending,0,0",
      );
      assert.equal(await hits("sink", "probe:rolls-back"), 0);
    });
  } catch (e) {
    // What the plane said is the only account of why it did not come up.
    console.error((await compose(["logs", "--tail", "40"])).stdout);
    throw e;
  } finally {
    await compose(["down", "-v", "--remove-orphans"]);
    const tagged = (await must(run("docker", ["image", "ls", "--format", "{{.Repository}}:{{.Tag}}"]), "list images")).split("\n").filter((i) => i.endsWith(`:${TAG}`));
    if (tagged.length > 0) await must(run("docker", ["image", "rm", ...tagged]), "remove this run's images");
    await Deno.remove(dir, { recursive: true });
  }
});
